import{_ as d,a0 as i,w as g,s as p,ao as l,I as n,x as e,a1 as s,A as r}from"./chunks/framework.C16IyNjs.js";import"./chunks/theme.CClUzVyq.js";const w=JSON.parse('{"title":"使用 Docker 和 Kubernetes 將 MongoDB 作為微服務運行 | LCTT x X-CMD","titleTemplate":false,"description":"使用 Docker 和 Kubernetes 將 MongoDB 作為微服務運行 | LCTT (201709) | X-CMD","frontmatter":{"pageClass":"x-lctt","head":[["meta",{"name":"og:title","content":"使用 Docker 和 Kubernetes 將 MongoDB 作為微服務運行 | LCTT x X-CMD"}],["meta",{"name":"og:description","content":"使用 Docker 和 Kubernetes 將 MongoDB 作為微服務運行 | LCTT (201709) | X-CMD"}]]},"headers":[],"params":{"isLCTT":true,"post":"201709/20160404 Running MongoDB as a Microservice with Docker and Kubernetes","title":"使用 Docker 和 Kubernetes 將 MongoDB 作為微服務運行","tag":"201709","desc":""},"relativePath":"201709/20160404 Running MongoDB as a Microservice with Docker and Kubernetes.md","filePath":"[post].md"}'),m={name:"201709/20160404 Running MongoDB as a Microservice with Docker and Kubernetes.md"};function u(b,o,a,D,M,B){const t=i("Link");return g(),p("div",null,[o[44]||(o[44]=l('<h1 id="使用-docker-和-kubernetes-將-mongodb-作為微服務運行" tabindex="-1">使用 Docker 和 Kubernetes 將 MongoDB 作為微服務運行 <a class="header-anchor" href="#使用-docker-和-kubernetes-將-mongodb-作為微服務運行" aria-label="Permalink to “使用 Docker 和 Kubernetes 將 MongoDB 作為微服務運行”">​</a></h1><h3 id="介紹" tabindex="-1">介紹 <a class="header-anchor" href="#介紹" aria-label="Permalink to “介紹”">​</a></h3><p><img src="https://webassets.mongodb.com/_com_assets/cms/bigstock-cargo-containers-96277130-377cd07c2b.jpg" alt=""></p><p>想在筆記本電腦上嘗試 MongoDB？只需執行一個命令，你就會有一個輕量級的、獨立的沙箱。完成後可以刪除你所做的所有痕跡。</p><p>想在多個環境中使用相同的<ruby>程序棧<rt>application stack</rt></ruby>副本？構建你自己的容器鏡像，讓你的開發、測試、運維和支持團隊使用相同的環境克隆。</p><p>容器正在徹底改變整個軟件生命週期：從最早的技術性實驗和概念證明，貫穿了開發、測試、部署和支持。</p><p>編排工具用來管理如何創建、升級多個容器，並使之高可用。編排還控制容器如何連接，以從多個微服務容器構建複雜的應用程序。</p><p>豐富的功能、簡單的工具和強大的 API 使容器和編排功能成為 DevOps 團隊的首選，將其集成到連續集成（CI） 和連續交付 （CD） 的工作流程中。</p><p>這篇文章探討了在容器中運行和編排 MongoDB 時遇到的額外挑戰，並説明了如何克服這些挑戰。</p><h3 id="mongodb-的注意事項" tabindex="-1">MongoDB 的注意事項 <a class="header-anchor" href="#mongodb-的注意事項" aria-label="Permalink to “MongoDB 的注意事項”">​</a></h3><p>使用容器和編排運行 MongoDB 有一些額外的注意事項：</p>',11)),n("ul",null,[o[9]||(o[9]=n("li",null,[e("MongoDB 資料庫節點是有狀態的。如果容器發生故障並被重新編排，數據則會丟失（能夠從副本集的其他節點恢復，但這需要時間），這是不合需要的。為了解決這個問題，可以使用諸如 Kubernetes 中的"),n("ruby",null,[e("數據卷"),n("rt",null,"volume")]),e(" 抽象等功能來將容器中臨時的 MongoDB 數據目錄映射到持久位置，以便數據在容器故障和重新編排過程中存留。")],-1)),o[10]||(o[10]=n("li",null,"一個副本集中的 MongoDB 資料庫節點必須能夠相互通信 - 包括重新編排後。副本集中的所有節點必須知道其所有對等節點的地址，但是當重新編排容器時，可能會使用不同的 IP 地址重新啓動。例如，Kubernetes Pod 中的所有容器共享一個 IP 地址，當重新編排 pod 時，IP 地址會發生變化。使用 Kubernetes，可以通過將 Kubernetes 服務與每個 MongoDB 節點相關聯來處理，該節點使用 Kubernetes DNS 服務提供“主機名”，以保持服務在重新編排中保持不變。",-1)),o[11]||(o[11]=n("li",null,[e("一旦每個單獨的 MongoDB 節點運行起來（每個都在自己的容器中），則必須初始化副本集，並添加每個節點到其中。這可能需要在編排工具之外提供一些額外的處理。具體來説，必須使用目標副本集中的一個 MongoDB 節點來執行 "),n("code",null,"rs.initiate"),e(" 和 "),n("code",null,"rs.add"),e(" 命令。")],-1)),o[12]||(o[12]=n("li",null,"如果編排框架提供了容器的自動化重新編排（如 Kubernetes），那麼這將增加 MongoDB 的彈性，因為這可以自動重新創建失敗的副本集成員，從而在沒有人為干預的情況下恢復完全的冗餘級別。",-1)),n("li",null,[o[4]||(o[4]=e("應該注意的是，雖然編排框架可能監控容器的狀態，但是不太可能監視容器內運行的應用程序或備份其數據。這意味着使用 ",-1)),s(t,{href:"https://www.mongodb.com/products/mongodb-enterprise-advanced"},{default:r(()=>[...o[0]||(o[0]=[e("MongoDB Enterprise Advanced",-1)])]),_:1}),o[5]||(o[5]=e(" 和 ",-1)),s(t,{href:"https://www.mongodb.com/products/mongodb-professional"},{default:r(()=>[...o[1]||(o[1]=[e("MongoDB Professional",-1)])]),_:1}),o[6]||(o[6]=e(" 中包含的 ",-1)),s(t,{href:"https://www.mongodb.com/cloud/"},{default:r(()=>[...o[2]||(o[2]=[e("MongoDB Cloud Manager",-1)])]),_:1}),o[7]||(o[7]=e(" 等強大的監控和備份解決方案非常重要。可以考慮創建自己的鏡像，其中包含你首選的 MongoDB 版本和 ",-1)),s(t,{href:"https://docs.cloud.mongodb.com/tutorial/nav/install-automation-agent/"},{default:r(()=>[...o[3]||(o[3]=[e("MongoDB Automation Agent",-1)])]),_:1}),o[8]||(o[8]=e("。",-1))])]),o[45]||(o[45]=n("h3",{id:"使用-docker-和-kubernetes-實現-mongodb-副本集",tabindex:"-1"},[e("使用 Docker 和 Kubernetes 實現 MongoDB 副本集 "),n("a",{class:"header-anchor",href:"#使用-docker-和-kubernetes-實現-mongodb-副本集","aria-label":"Permalink to “使用 Docker 和 Kubernetes 實現 MongoDB 副本集”"},"​")],-1)),o[46]||(o[46]=n("p",null,"如上節所述，分佈式資料庫（如 MongoDB）在使用編排框架（如 Kubernetes）進行部署時，需要稍加註意。本節將介紹詳細介紹如何實現。",-1)),o[47]||(o[47]=n("p",null,"我們首先在單個 Kubernetes 集羣中創建整個 MongoDB 副本集（通常在一個數據中心內，這顯然不能提供地理冗餘）。實際上，很少有必要改變成跨多個集羣運行，這些步驟將在後面描述。",-1)),o[48]||(o[48]=n("p",null,"副本集的每個成員將作為自己的 pod 運行，並提供一個公開 IP 地址和端口的服務。這個“固定”的 IP 地址非常重要，因為外部應用程序和其他副本集成員都可以依賴於它在重新編排 pod 的情況下保持不變。",-1)),o[49]||(o[49]=n("p",null,"下圖説明了其中一個 pod 以及相關的複製控制器和服務。",-1)),o[50]||(o[50]=n("p",null,[n("img",{src:"https://webassets.mongodb.com/_com_assets/cms/image04-0b13b8ba36.png",alt:""})],-1)),o[51]||(o[51]=n("p",null,[n("em",null,"圖 1：MongoDB 副本集成員被配置為 Kubernetes Pod 並作為服務公開")],-1)),o[52]||(o[52]=n("p",null,"逐步介紹該配置中描述的資源：",-1)),n("ul",null,[n("li",null,[o[14]||(o[14]=e("從核心開始，有一個名為 ",-1)),o[15]||(o[15]=n("code",null,"mongo-node1",-1)),o[16]||(o[16]=e(" 的容器。",-1)),o[17]||(o[17]=n("code",null,"mongo-node1",-1)),o[18]||(o[18]=e(" 包含一個名為 ",-1)),o[19]||(o[19]=n("code",null,"mongo",-1)),o[20]||(o[20]=e(" 的鏡像，這是一個在 ",-1)),s(t,{href:"https://hub.docker.com/_/mongo/"},{default:r(()=>[...o[13]||(o[13]=[e("Docker Hub",-1)])]),_:1}),o[21]||(o[21]=e(" 上託管的一個公開可用的 MongoDB 容器鏡像。容器在集羣中暴露端口 ",-1)),o[22]||(o[22]=n("code",null,"27107",-1)),o[23]||(o[23]=e("。",-1))]),o[24]||(o[24]=l("<li>Kubernetes 的數據卷功能用於將連接器中的 <code>/data/db</code> 目錄映射到名為 <code>mongo-persistent-storage1</code> 的永久存儲上，這又被映射到在 Google Cloud 中創建的名為 <code>mongodb-disk1</code> 的磁盤中。這是 MongoDB 存儲其數據的地方，這樣它可以在容器重新編排後保留。</li><li>容器保存在一個 pod 中，該 pod 中有標籤命名為 <code>mongo-node</code>，並提供一個名為 <code>rod</code> 的（任意）示例。</li><li>配置 <code>mongo-node1</code> 複製控制器以確保 <code>mongo-node1</code> pod 的單個實例始終運行。</li><li>名為 <code>mongo-svc-a</code> 的 <code>負載均衡</code> 服務給外部開放了一個 IP 地址以及 <code>27017</code> 端口，它被映射到容器相同的端口號上。該服務使用選擇器來匹配 pod 標籤來確定正確的 pod。外部 IP 地址和端口將用於應用程序以及副本集成員之間的通信。每個容器也有本地 IP 地址，但是當容器移動或重新啓動時，這些 IP 地址會變化，因此不會用於副本集。</li>",4))]),o[53]||(o[53]=l('<p>下一個圖顯示了副本集的第二個成員的配置。</p><p><img src="https://webassets.mongodb.com/_com_assets/cms/image00-f5bc4ecaf8.png" alt=""></p><p><em>圖 2：第二個 MongoDB 副本集成員配置為 Kubernetes Pod</em></p><p>90％ 的配置是一樣的，只有這些變化：</p><ul><li>磁盤和卷名必須是唯一的，因此使用的是 <code>mongodb-disk2</code> 和 <code>mongo-persistent-storage2</code></li><li>Pod 被分配了一個 <code>instance: jane</code> 和 <code>name: mongo-node2</code> 的標籤，以便新的服務可以使用選擇器與圖 1 所示的 <code>rod</code> Pod 相區分。</li><li>複製控制器命名為 <code>mongo-rc2</code></li><li>該服務名為<code> mongo-svc-b</code>，並獲得了一個唯一的外部 IP 地址（在這種情況下，Kubernetes 分配了 <code>104.1.4.5</code>）</li></ul><p>第三個副本成員的配置遵循相同的模式，下圖展示了完整的副本集：</p><p><img src="https://webassets.mongodb.com/_com_assets/cms/image01-b1896be8f6.png" alt=""></p><p><em>圖 3：配置為 Kubernetes 服務的完整副本集成員</em></p><p>請注意，即使在三個或更多節點的 Kubernetes 羣集上運行圖 3 所示的配置，Kubernetes 可能（並且經常會）在同一主機上編排兩個或多個 MongoDB 副本集成員。這是因為 Kubernetes 將三個 pod 視為屬於三個獨立的服務。</p><p>為了在區域內增加冗餘，可以創建一個附加的 <em>headless</em> 服務。新服務不向外界提供任何功能（甚至不會有 IP 地址），但是它可以讓 Kubernetes 通知三個 MongoDB pod 形成一個服務，所以 Kubernetes 會嘗試在不同的節點上編排它們。</p><p><img src="https://webassets.mongodb.com/_com_assets/cms/image02-5769db88c4.png" alt=""></p><p><em>圖 4：避免同一 MongoDB 副本集成員的 Headless 服務</em></p>',12)),n("p",null,[o[26]||(o[26]=e("配置和啓動 MongoDB 副本集所需的實際配置文件和命令可以在白皮書《",-1)),s(t,{href:"https://www.mongodb.com/collateral/microservices-containers-and-orchestration-explained"},{default:r(()=>[...o[25]||(o[25]=[e("啓用微服務：闡述容器和編排",-1)])]),_:1}),o[27]||(o[27]=e("》中找到。特別的是，需要一些本文中描述的特殊步驟來將三個 MongoDB 實例組合成具備功能的、健壯的副本集。",-1))]),o[54]||(o[54]=l('<h4 id="多個可用區域-mongodb-副本集" tabindex="-1">多個可用區域 MongoDB 副本集 <a class="header-anchor" href="#多個可用區域-mongodb-副本集" aria-label="Permalink to “多個可用區域 MongoDB 副本集”">​</a></h4><p>上面創建的副本集存在風險，因為所有內容都在相同的 GCE 集羣中運行，因此都在相同的<ruby>可用區<rt>availability zone</rt></ruby>中。如果有一個重大事件使可用區離線，那麼 MongoDB 副本集將不可用。如果需要地理冗餘，則三個 pod 應該在三個不同的可用區或地區中運行。</p><p>令人驚奇的是，為了創建在三個區域之間分割的類似的副本集（需要三個集羣），幾乎不需要改變。每個集羣都需要自己的 Kubernetes YAML 文件，該文件僅為該副本集中的一個成員定義了 pod、複製控制器和服務。那麼為每個區域創建一個集羣，永久存儲和 MongoDB 節點是一件很簡單的事情。</p><p><img src="https://webassets.mongodb.com/_com_assets/cms/image03-d16cbbfe42.png" alt=""></p><p><em>圖 5：在多個可用區域上運行的副本集</em></p><h3 id="下一步" tabindex="-1">下一步 <a class="header-anchor" href="#下一步" aria-label="Permalink to “下一步”">​</a></h3>',6)),n("p",null,[o[29]||(o[29]=e("要了解有關容器和編排的更多信息 - 所涉及的技術和所提供的業務優勢 - 請閲讀白皮書《",-1)),s(t,{href:"https://www.mongodb.com/collateral/microservices-containers-and-orchestration-explained"},{default:r(()=>[...o[28]||(o[28]=[e("啓用微服務：闡述容器和編排",-1)])]),_:1}),o[30]||(o[30]=e("》。該文件提供了獲取本文中描述的副本集，並在 Google Container Engine 中的 Docker 和 Kubernetes 上運行的完整的説明。",-1))]),o[55]||(o[55]=n("hr",null,null,-1)),o[56]||(o[56]=n("p",null,"作者簡介：",-1)),o[57]||(o[57]=n("p",null,"Andrew 是 MongoDB 的產品營銷總經理。他在去年夏天離開 Oracle 加入 MongoDB，在 Oracle 他花了 6 年多的時間在產品管理上，專注於高可用性。他可以通過 @andrewmorgan 或者在他的Blog（clusterdb.com）評論聯繫他。",-1)),o[58]||(o[58]=n("hr",null,null,-1)),n("p",null,[o[32]||(o[32]=e("via: ",-1)),s(t,{href:"https://www.mongodb.com/blog/post/running-mongodb-as-a-microservice-with-docker-and-kubernetes"},{default:r(()=>[...o[31]||(o[31]=[e("https://www.mongodb.com/blog/post/running-mongodb-as-a-microservice-with-docker-and-kubernetes",-1)])]),_:1})]),n("p",null,[o[36]||(o[36]=e("作者：",-1)),s(t,{href:"http://www.clusterdb.com/"},{default:r(()=>[...o[33]||(o[33]=[e("Andrew Morgan",-1)])]),_:1}),o[37]||(o[37]=e(" 譯者：",-1)),s(t,{href:"https://github.com/geekpi"},{default:r(()=>[...o[34]||(o[34]=[e("geekpi",-1)])]),_:1}),o[38]||(o[38]=e(" 校對：",-1)),s(t,{href:"https://github.com/wxy"},{default:r(()=>[...o[35]||(o[35]=[e("wxy",-1)])]),_:1})]),n("p",null,[o[41]||(o[41]=e("本文由 ",-1)),s(t,{href:"https://github.com/LCTT/TranslateProject"},{default:r(()=>[...o[39]||(o[39]=[e("LCTT",-1)])]),_:1}),o[42]||(o[42]=e(" 原創編譯，",-1)),s(t,{href:"https://linux.cn/"},{default:r(()=>[...o[40]||(o[40]=[e("Linux中國",-1)])]),_:1}),o[43]||(o[43]=e(" 榮譽推出",-1))])])}const T=d(m,[["render",u]]);export{w as __pageData,T as default};
